#include <stdio.h>

void twice(int *p, int n) {
    for (int i = 0; i < n; i++) {
        p[i] = p[i] * 2;
    }
}

int main(void) {
    int bowls[8];
    int n;

    if (scanf("%d", &n) != 1) {
        return 1;
    }
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &bowls[i]) != 1) {
            return 1;
        }
    }

    printf("翻倍前\n");
    for (int i = 0; i < n; i++) {
        printf("第 %d 只：%d\n", i, bowls[i]);
    }

    twice(bowls, n);

    printf("翻倍后\n");
    for (int i = 0; i < n; i++) {
        printf("第 %d 只：%d\n", i, bowls[i]);
    }
    return 0;
}

